mapper.insert:
set foreign_key_checks = 0;
insert into sys_user_notice (user_id, notice_id, create_time)
values

    (#{item}, #{id}, now())

;
set foreign_key_checks = 1;

mapper.select:
select count(*) from sys_notice


        title like concat('%', #{title}, '%')


        and notice_type = #{noticeType}


        and status = #{status}


        and to_range = #{toRange}


        and priority = #{priority}


        and publisher = #{publisher}

select n.*, u.username as parsedPublisher from sys_notice n
left join sys_user u on n.publisher = u.user_id


        n.title like concat('%', #{title}, '%')


        and n.notice_type = #{noticeType}


        and n.status = #{status}


        and n.to_range = #{toRange}


        and n.priority = #{priority}


        and n.publisher = #{publisher}


order by n.id

    limit #{offSet} , #{pageSize}
